import { l4 } from './src/data/l4.ts';
import { l4PerimeterWalls } from './src/data/l4Perimeter.ts';
import { loadL4, runL4 } from './tools/sim-runner/l4Bots.ts';
const {world:w,mission:m}=await loadL4(1,'high');
const nav=w.infected!.nav, player=w.entities.get(1)!;
const distanceToWire=(x:number,z:number)=>Math.min(...l4PerimeterWalls.map(q=>Math.hypot(Math.max(0,Math.abs(x-q.x)-q.halfX),Math.max(0,Math.abs(z-q.z)-q.halfZ))));
const windows=new Map<number,{tick:number;x:number;z:number;travel:number}[]>();
const stopped:unknown[]=[]; let rollingWindows=0;
const held=new Map<number,{seconds:number;start:number;last:{x:number;z:number};travel:number;arch:string;nearest:number}>();
const qualifying=new Map<number,{id:number;arch:string;seconds:number;start:number;end:number;travel:number;nearest:number}>();
let ticks=0, eligibleTicks=0, nearTicks=0, maxActors=0;
const report=runL4(w,m,'complete',{seed:1,god:true,maxSeconds:520,stopWhen:()=>{
 ticks++;
 const p=player.transform, goal=nav.nearestCell(p.x,p.z,.35);
 const seen=new Set<number>();
 for(const e of w.infected!.active){
  if(e.health.current<=0||e.hidden||e.emerging||!e.infected) continue;
  const near=distanceToWire(e.transform.x,e.transform.z);
  if(near>2 || !(e.transform.x<l4.perimeter.x0 || e.transform.x>l4.perimeter.x1 || e.transform.z<l4.perimeter.z0 || e.transform.z>l4.perimeter.z1)) continue;
  nearTicks++;
  const from=nav.nearestCell(e.transform.x,e.transform.z,e.combat?.radius??.35);
  const path:number[]=[];
  const route=from>=0&&goal>=0&&nav.path(from,goal,path,1000000);
  if(!route) continue;
  eligibleTicks++; seen.add(e.id);
  const window=windows.get(e.id)??[];
  const last=window.at(-1), travel=(last?.travel??0)+(last?Math.hypot(e.transform.x-last.x,e.transform.z-last.z):0);
  window.push({tick:w.tick,x:e.transform.x,z:e.transform.z,travel});
  while(window.length && window[0].tick<w.tick-301) window.shift();
  windows.set(e.id,window);
  if(window.length>301){
   rollingWindows++;
   const first=window[0], movement=travel-first.travel;
   if(movement<.1 && !stopped.some((q:any)=>q.id===e.id)) stopped.push({id:e.id,archetype:e.archetype,start:first.tick,end:w.tick,travel:movement,position:{...e.transform},state:e.infected.state,scripted:e.infected.scripted,brain:e.infected.l1,targetId:e.infected.targetId});
  }
  const row=held.get(e.id), delta=row?Math.hypot(e.transform.x-row.last.x,e.transform.z-row.last.z):0;
  if(row){row.seconds++;row.travel+=delta;row.last={x:e.transform.x,z:e.transform.z};row.nearest=Math.min(row.nearest,near);}
  else held.set(e.id,{seconds:1,start:w.tick,last:{x:e.transform.x,z:e.transform.z},travel:0,arch:e.archetype??'unknown',nearest:near});
  const h=held.get(e.id)!;
  if(h.seconds>=300) qualifying.set(e.id,{id:e.id,arch:h.arch,seconds:h.seconds/60,start:h.start,end:w.tick,travel:+h.travel.toFixed(2),nearest:+h.nearest.toFixed(2)});
 }
 for(const id of held.keys()) if(!seen.has(id)) {held.delete(id);windows.delete(id);}
 maxActors=Math.max(maxActors,held.size);
 return false;
}});
console.log(JSON.stringify({seed:1,tier:'high',profile:'complete',outcome:report.outcome,ticks,phase:m.state.phase,turnAt:m.state.l4?.turnAt,eligibleTicks,nearTicks,maxConcurrentCandidates:maxActors,rollingWindows,stationaryThresholdM:.1,stopped,qualifyingCount:qualifying.size,qualifying:[...qualifying.values()]}));
w.dispose();

wreckSweepRecipe.source:
import { SceneSession,stopServer } from './tools/scenelab/session.ts';
import {mkdirSync,writeFileSync} from 'node:fs';
const level=process.argv[2]??'L3',backend=process.argv[3]??'webgl2';const s=new SceneSession({backend:backend as any,tier:'high'});const out=`test-results/s140-wreckground/sweep-${level}-${backend}`;mkdirSync(out,{recursive:true});
try{await s.open();await s.page.evaluate('globalThis.__name = fn => fn');const targets=await s.page.evaluate(async level=>{const a=window.__SS__!;await a.loadLevel(level,{seed:1});a.pause();a.missions.begin();await a.screenshotReady();const g=(window as any).__SCENE__.game;return g.world.districts.districts.flatMap(d=>d.decay.placements.filter(p=>p.assetId.startsWith('veh.')&&(p.assetId==='veh.wreck'||['wrecked','burned'].includes(p.decay))).map(p=>({id:`${d.id}/${p.id}`,x:p.position[0]+d.origin[0],y:p.position[1],z:p.position[2]+d.origin[1]})));},level);const rows=[];for(const p of targets){const row=await s.page.evaluate(async p=>{const a=window.__SS__!;a.camera.cinematic({position:[p.x+10,p.y+10,p.z+10],target:[p.x,p.y+.6,p.z]},true);await a.screenshotReady();await new Promise(r=>setTimeout(r,250));await a.screenshotReady();const g=(window as any).__SCENE__.game;return g.view.labProbes().districts.wreckGroundGaps().find(q=>q.id===p.id)??null;},p);rows.push({requested:p.id,result:row});console.log(JSON.stringify({id:p.id,gapCm:row?.gapCm,lod:row?.lod}));writeFileSync(`${out}/gaps.json`,JSON.stringify({level,backend,targets:targets.length,rows},null,2));}}finally{await s.close();stopServer();}

westAlphaFocused.source:
import {loadL4} from './tools/sim-runner/l4Bots.ts';
import {l4Breaches} from './src/data/l4Perimeter.ts';
const {world:w,mission:m}=await loadL4(1,'high');try{m.loadCheckpoint('turn');for(const e of [...w.infected!.active])w.infected!.release(e);for(const e of w.entities.iterate())if(e.civilian)e.hidden=true;for(const i of l4Breaches.west.segments){const id=`l4-wall-${i}`,e=[...w.entities.iterate()].find(e=>e.barricade?.slot.id===id)!;e.barricade!.intact=false;e.kind='device';w.solids.setBarrier(id,null);}m.state.l4!.breaches={west:{announcedAt:w.tick,openAt:w.tick}};const id=w.infected!.spawn('infected.alpha',{x:-36.74867099529254,z:3.7673575875408876}),e=w.entities.get(id)!;e.infected!.scripted={x:-32.1,z:6.105882352941178};const start={...e.transform};for(let i=0;i<600;i++)w.update();console.log(JSON.stringify({id,start,end:e.transform,travel:Math.hypot(e.transform.x-start.x,e.transform.z-start.z),scripted:e.infected!.scripted}));}finally{w.dispose();}

