import {readFileSync} from 'node:fs';
import {GLTFLoader} from './node_modules/three/examples/jsm/loaders/GLTFLoader.js';
import {MeshoptDecoder} from './node_modules/three/examples/jsm/libs/meshopt_decoder.module.js';
import {GroundField} from './src/render/GroundField.ts';
const loader=new GLTFLoader().setMeshoptDecoder(MeshoptDecoder),field=new GroundField();
for(const tier of ['base','w1','w2','w3','w4','w5','w6']){const b=readFileSync(`public/assets/layouts/D-FAIR.${tier}.glb`),g=await loader.parseAsync(b.buffer.slice(b.byteOffset,b.byteOffset+b.byteLength),'');g.scene.updateMatrixWorld(true);g.scene.traverse(n=>{if((n as any).isMesh&&typeof n.userData.assetId!=='string')field.add(n as any,Infinity);});}
let worst={x:0,z:0,h:-Infinity};for(let x=134;x<=142;x+=.1)for(let z=22;z<=28;z+=.1){const h=field.height(x,z)??-Infinity;if(h>worst.h)worst={x,z,h};} console.log(JSON.stringify({worst}));console.log(JSON.stringify({triangles:field.triangles,centers:[214,138,100].map(x=>({x,z:25,high:field.height(x,25),below4:field.height(x,25,4)}))}));
